    HighValue = 0,
    /// 存在且有一定区分度。
    Secondary = 1,
    /// 几乎处处命中：无区分度，等价于停用词。
    Stopword = 2,
    /// 工作区里不存在。
    Absent = 3,
}

impl AnchorGrade {
    pub fn is_locatable(self) -> bool {
        matches!(self, Self::HighValue | Self::Secondary)
    }
}

