/// 历史面板相对时间展示（刚刚 / N 分钟前 / N 小时前 / N 天前）。
fn relative_time(t: &std::time::SystemTime) -> String {
    let Ok(ago) = t.elapsed() else {
        return "刚刚".into();
    };
    let secs = ago.as_secs();
    if secs < 60 {
        "刚刚".into()
    } else if secs < 3600 {
        format!("{} 分钟前", secs / 60)
    } else if secs < 86400 {
        format!("{} 小时前", secs / 3600)
    } else {
        format!("{} 天前", secs / 86400)
    }
}

/// 诊断追踪：macOS 写 Application Support，其余平台写到 exe 目录。
fn trace(line: &str) {
    if let Some(dir) = crate::settings::app_data_dir() {
        let _ = std::fs::create_dir_all(&dir);
        let p = dir.join("harness_gui_trace.log");
        // 体积封顶：超过 4MB 把旧日志降级为 .old（覆盖上一次），防止无限增长。
        if let Ok(meta) = std::fs::metadata(&p) {
            if meta.len() > 4 * 1024 * 1024 {
                let _ = std::fs::rename(&p, dir.join("harness_gui_trace.log.old"));
            }
        }
        use std::io::Write;
        if let Ok(mut f) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&p)
        {
            let _ = writeln!(f, "[{}] {}", now_ms(), line);
        }
    }
}

fn now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis() as u64)
        .unwrap_or(0)
}

