#[cfg(target_os = "windows")]
use std::os::windows::process::CommandExt;

use harness_capability::git::{Git, GitChange, GitStatus, Worktree};
use harness_core::error::{Error, Result};
use harness_core::Workspace;

/// 创建静默执行的 git 命令。
///
/// Windows 下 GUI 进程每次 fork 子进程默认会分配一个控制台窗口：点击文件树 /
/// Git Diff 时高频调用 git 会连续弹出黑色 CMD 窗口闪烁。`CREATE_NO_WINDOW`
/// (0x08000000) 让子进程完全后台运行，消除闪烁；非 Windows 平台无此问题。
fn git_command() -> Command {
    let mut cmd = Command::new("git");
    #[cfg(target_os = "windows")]
    {
        const CREATE_NO_WINDOW: u32 = 0x0800_0000;
        cmd.creation_flags(CREATE_NO_WINDOW);
    }
    cmd
}

/// 把 git 原始 stderr 映射为可行动的中文错误。
///
/// 非 Git 仓库的工作区是合法场景（用户可打开任意目录），把 `fatal: not a git
/// repository...` 这类底层 stderr 直接抛给 UI 只会让用户看到一串无法理解的
/// 报错；这里统一转为一句明确的说明，UI 层可据此优雅降级。
fn friendly_git_error(stderr: &str) -> Option<Error> {
    if stderr.contains("not a git repository") {
        return Some(Error::Git(
            "当前工作区不是 Git 仓库（未检测到 .git），Git 功能不可用".into(),
        ));
    }
    None
}

